Fonctions JS
Méthodes de l’objet Math
Nom 	Description
alert("msg") 	Affiche un message dans une boite de dialogue
document.write("msg") 	Affiche directement me message dans le document HTML
Nom 	Description
prompt("msg") 	Affiche une boite de dialogue avec le titre "msg" et une zone de saisie
Nom 	Description 	Exemple 	Résultat
isNaN(a) Fonction qui retourne vrai si a n’est pas un
nombre, sinon elle retourne faux
let b = isNaN(123);
let b = isNaN("123");
let b = isNaN("Bob");
b = False
b = False
b = True
Number(ch) 	Fonction qui convertit une chaine ch en un nombre
let n = Number(true);
let n = Number(false);
let n = Number(123);
let n = Number(-123);
let n = Number("10");
let n = Number("-10");
let n = Number("10.5");
let n = Number("Bob");
let n = Number(5e3);
let n = Number(5e-3);
let n = Number("");
n = 1
n = 0
n = 123
n = -123
n = 10
n = -10
n = 10.5
n = NaN
n = 5000
n = 0.005
n = 0
parseInt(ch,b) Fonction qui convertit une chaine ch en un entier
exprimé dans la base b
let n = parseInt("101", 2)
let n = parseInt("10");
let n = parseInt("10.5");
let n = parseInt("10 20 30");
let n = parseInt("10 years");
let n =parseInt("years 10");
n = 5
n = 10
n = 10
n = 10
n = 10
NaN
parseFloat(ch) 	Fonction qui convertit une chaine ch en réel
let n = parseFloat("10");
let n = parseFloat("10.5");
let n = parseFloat("10 20 30");
let n = parseFloat("10 years");
let n = parseFloat("years 10");
n = 10
n = 10.5
n = 10
n = 10
NaN
String(a) 	Fonction qui convertit la valeur a en chaine 	let ch = String(123); 	ch = "123"
Nom 	Description 	Exemple 	Résultat
Math.abs(x) 	Méthode qui retourne la valeur absolue de x 	let n = Math.abs(-3); 	n = 3
Math.round(x) 	Méthode qui retourne l'entier arrondi le plus proche de x let n = Math.round(5.5);
let n = Math.round(6.1);
n = 6
n = 6
Math.trunc(x) Méthode qui retourne la partie entière de x et retire la
partie décimale let n = Math.trunc(5.9); 	n = 5
Math.sqrt(x) 	Méthode qui retourne la racine carrée de x 	let n = Math.sqrt(64); 	n = 8
Math.random() 	Méthode qui retourne un réel au hasard entre 0 et 1 	let n = Math.random(); 	n = 0.7

